import React from 'react';
import './Experience.css';

const Experience = () => {
  const experiences = [
    {
      title: "Computer Science Graduate Researcher",
      company: "Tech Corporation",
      period: "2022 - Present",
      location: "San Francisco, CA",
      description: [
        "Led a team of 5 developers in building scalable web applications using React and Node.js",
        "Architected and implemented microservices that improved system performance by 40%",
        "Mentored junior developers and established coding standards and best practices",
        "Collaborated with product managers to define technical requirements and project timelines"
      ]
    },
    {
      title: "Software Engineer Intern",
      company: "Google",
      period: "2024 - 2024",
      location: "New York, NY",
      description: [
        "Developed full-stack applications using modern JavaScript frameworks and cloud technologies",
        "Implemented automated testing strategies that reduced bugs in production by 60%",
        "Optimized database queries and API endpoints for better performance",
        "Participated in code reviews and contributed to technical documentation"
      ]
    },
    {
      title: "Junior Software Developer",
      company: "StartUp Inc.",
      period: "2019 - 2020",
      location: "Boston, MA",
      description: [
        "Built responsive web interfaces using React, HTML5, and CSS3",
        "Integrated third-party APIs and services to enhance application functionality",
        "Worked in an Agile environment with cross-functional teams",
        "Contributed to the development of the company's main product platform"
      ]
    },
    {
      title: "Research Assistant",
      company: "University Research Lab",
      period: "2018 - 2019",
      location: "Cambridge, MA",
      description: [
        "Conducted research on machine learning algorithms for natural language processing",
        "Published findings in peer-reviewed conferences and journals",
        "Developed prototypes and proof-of-concepts for research projects",
        "Collaborated with PhD students and faculty on various research initiatives"
      ]
    }
  ];

  return (
    <section id="experience" className="section">
      <div className="container">
        <h2 className="section-title">Work Experience</h2>
        <div className="experience-timeline">
          {experiences.map((exp, index) => (
            <div key={index} className="experience-item">
              <div className="experience-content card">
                <div className="experience-header">
                  <h3 className="experience-title">{exp.title}</h3>
                  <div className="experience-meta">
                    <span className="experience-company">{exp.company}</span>
                    <span className="experience-period">{exp.period}</span>
                    <span className="experience-location">{exp.location}</span>
                  </div>
                </div>
                <ul className="experience-description">
                  {exp.description.map((item, idx) => (
                    <li key={idx}>{item}</li>
                  ))}
                </ul>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Experience;
